[8757]=[=[{o="Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the invoker will greatly enhance your magical and natural abilities.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind.",k=false}]=],
[8758]=[=[{o="Your continued defense of the children of Kalimdor has been acknowledged. Hand me your signet ring so that I may enhance its powers.",k=false}]=],
