[8760]=[=[{o="Dedication of this magnitude is a rarity. You have shown that your will is unfaltering, <name>. You shall be greatly rewarded for your stalwart watch over our world.\n\nHand me your signet ring so that I may strengthen its enchantment.",k=false}]=],
