[8798]=[=[{o="Say! You know what?! You're an engineer too! So, since you helped me teach my friends a lesson, I'm going to teach you how to make your very own mechanical yeti! Now the fun can go on forever and ever, and you can scare whoever you want! Provided that you can scare up the components to make it that is.\n\nWhat do you say, <name>? Do you want to learn the secret to making a mechanical yeti?",k=false}]=],
[8800]=[=[{o="Talk to Vargus at Cenarion Hold in Silithus.",d="As you complete the tasks you're assigned in the war you'll want to talk to Vargus, the blacksmith.  Show him any badges you've earned along the way. He'll provide you with gear to match your level of commitment to our cause.",c="Kaldon sent you? Very well, let's see what we can do for you.",r={rep={{609,10}}},k=true}]=],
[8913]=[=[{o="Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Wildheart Bracers to Mokvar in Orgrimmar.",n={{"Silithus Venom Sample",15}},d="Hail, <class>!  I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.\n\nPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.\n\nI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange.",p="Have you obtained the items I require, <name>?",c="Ah, yes. Mux will be quite happy with this.\n\nThose bracers were part of a larger armor set. If you're interested in providing me with further assistance, I'd be willing to consider parting with the rest of it.",r={it={{22108,1,"Feralheart Bracers",3,"inv_bracer_09"}}},k=true}]=],
