[9023]=[=[{o="Dirk Thunderwood at Cenarion Hold wants you to bring him Venoxis's Venom Sac and Kurinnaxx's Venom Sac.",d="My brother and I run the poison operations out of the manor Ravenholdt.\n\nLord Ravenholdt tasked me to track down a new and extremely effective poison compound that can be crafted from the venom sacs of the inhabitants of Zul'Gurub and the Ruins of Ahn'Qiraj.\n\nThere are two particularly venomous beasts residing in those blasted ruins that possess what it is that we might be looking for, <class>. Bring me a venom sac from the beasts Kurinnaxx and Venoxis and we would be eternally grateful.",p="This ain't no smash and grab job, <name>. You're gonna need to bring friends.",c="Ravenholdt thanks you, hero! Take your pick!",r={ch={{22378,1,"Ravenholdt Slicer",3,"inv_sword_38"},{22379,1,"Shivsprocket's Shiv",3,"inv_sword_21"},{22377,1,"The Thunderwood Poker",3,"inv_sword_17"},{22348,1,"Doomulus Prime",3,"inv_hammer_10"},{22347,1,"Fahrad's Reloading Repeater",3,"inv_weapon_crossbow_04"},{22380,1,"Simone's Cultivating Hammer",3,"inv_hammer_05"}},rep={{609,250}}},k=true}]=],
[9248]=[=[{o="Aurel Goldleaf at Cenarion Hold in Silithus wants you to bring her 1 Abyssal Scepter. You must also be Honored with the Cenarion Circle.",d="Ishnu-alah, <race>. Show me proof of the demise of a Lord of the Abyssal Council and I shall reward you with an item that should aid you in your battles against the Qiraji.",p="Fandu-dath-belore? Oh, pardon me, <name>. I did not recognize you. Have you the scepter?",c="Ande'thoras-ethil. It means; 'May your troubles be diminished,' in my native tongue.\n\nWear the band proudly and in good health, <name>.",r={it={{22725,1,"Band of Cenarius",3,"inv_jewelry_ring_11"}},rep={{609,200}}},k=true}]=],
[9415]=[=[{o="Speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.",d="Are you Marshal Bluewall's new recruits? Of course you are.\n\nWhat are you waiting for? Good soldiers are dying in the desert. Aren't you excited to join them?\n\nNow, get going and don't dry out on the way.",c="The Alliance needs every able body they can get. The Horde has been receiving a steady supply of reinforcements from the northern part of the continent, and it's been a struggle to keep up.\n\nLet me explain the situation to you.",k=true}]=],
[9416]=[=[{o="Speak with General Kirika at the Horde encampment near Hive'Regal.",d="You must be one of General Kirika's new recruits. It's about time you showed up. Bodies wear down quick in the desert.\n\nThe dwarves have been getting reinforcements daily, and we can't afford to lose ground in our struggle for resources in Silithus.\n\nGet your instructions from the General. It's not my job to train you, just find you.",c="It's good that you're here, but there's no time to waste making small talk. You need instructions, and then you need to get out there.\n\nListen up.",k=true}]=],
[9419]=[=[{o="Find and deliver Silithyst to the Silithyst Extractor, then speak with Marshal Bluewall at the Alliance encampment near Hive'Zora.",d="We recently found out that the Horde has been scavenging the Silithus desert for resources, but paid them little mind. We thought it could not be worth it to station large numbers in this sweltering desert.\n\nHowever, it was discovered the importance of the resources, and now we are scrambling to catch up.\n\nIf I have your assistance, you must go into the desert and recover the silithyst and return it here.",p="Be careful out there, but also be quick. We have no time to lose.",c="Thank the Light you were successful.\n\nNow if we could only have started this sooner, our need would not be so desperate. We must keep the bounty of the desert from falling into the hands of the Horde.",r={ch={{13446,2,"Major Healing Potion",1,"inv_potion_54"},{13444,2,"Major Mana Potion",1,"inv_potion_76"}},rep={{609,250}}},k=true}]=],
[9422]=[=[{o="Find and deliver Silithyst to the Silithyst Extractor then speak with General Kirika at the Horde encampment near Hive'Regal.",d="For some time now, we have been tapping the crystal resources of the Silithus desert. The only dangers we faced were from the creatures that made this place their home and the oppressive sand and dust and heat.\n\nBut now the Alliance seems to have caught on to what we have found here. It is now a race between us to capture the natural resources, and keep them from the other.\n\nI need every set of hands that is available. I hope I have yours.",p="Be wary of the dangers of the desert, <name>. With the Alliance lurking in the dunes, any step could be your last.",c="You've done well, <name>. These resources will be added to our stockpiles, and every bit is to our gain and our enemy's loss.",r={ch={{13446,2,"Major Healing Potion",1,"inv_potion_54"},{13444,2,"Major Mana Potion",1,"inv_potion_76"}},rep={{609,250}}},k=true}]=],
